CREATE TABLE lab_runs(id varchar(80) PRIMARY KEY, policy varchar(16) NOT NULL, trust_email boolean NOT NULL DEFAULT false, terms_version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id uuid PRIMARY KEY, realm_id varchar(80) NOT NULL REFERENCES lab_runs(id) ON DELETE CASCADE, name varchar(60) NOT NULL, status varchar(16) NOT NULL DEFAULT 'ACTIVE', auth_version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(realm_id,id));
CREATE TABLE account_emails(account_id uuid PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE, realm_id varchar(80) NOT NULL, original_email varchar(254) NOT NULL, email_key varchar(254) NOT NULL, verified_at timestamptz NOT NULL, proof_source varchar(40) NOT NULL, UNIQUE(realm_id,email_key), FOREIGN KEY(realm_id,account_id) REFERENCES accounts(realm_id,id));
CREATE TABLE password_credentials(account_id uuid PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE, encoded_hash varchar(512) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE external_identities(id uuid PRIMARY KEY, realm_id varchar(80) NOT NULL, account_id uuid NOT NULL, issuer varchar(300) NOT NULL, subject varchar(255) NOT NULL, provider varchar(20) NOT NULL, linked_at timestamptz NOT NULL DEFAULT now(), UNIQUE(realm_id,issuer,subject), FOREIGN KEY(realm_id,account_id) REFERENCES accounts(realm_id,id));
CREATE TABLE signup_flows(id uuid PRIMARY KEY, realm_id varchar(80) NOT NULL REFERENCES lab_runs(id) ON DELETE CASCADE, cookie_hash varchar(64) NOT NULL UNIQUE, status varchar(16) NOT NULL DEFAULT 'OPEN', intent varchar(16) NOT NULL DEFAULT 'LOCAL', email_original varchar(254), email_key varchar(254), generation int NOT NULL DEFAULT 0, issued_count int NOT NULL DEFAULT 0, last_issued_at timestamptz, verified_at timestamptz, verified_until timestamptz, proof_source varchar(40), account_id uuid REFERENCES accounts(id), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE TABLE email_challenges(id uuid PRIMARY KEY, flow_id uuid NOT NULL REFERENCES signup_flows(id) ON DELETE CASCADE, generation int NOT NULL, email_key varchar(254) NOT NULL, token_hash varchar(64) NOT NULL, state varchar(20) NOT NULL DEFAULT 'ACTIVE', issued_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, consumed_at timestamptz, UNIQUE(flow_id,generation));
CREATE TABLE signup_operation_results(flow_id uuid NOT NULL REFERENCES signup_flows(id) ON DELETE CASCADE, operation varchar(24) NOT NULL, idem_key varchar(80) NOT NULL, request_hmac varchar(64) NOT NULL, hmac_key_id varchar(16) NOT NULL DEFAULT 'v1', status int NOT NULL, outcome jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(flow_id,operation,idem_key));
CREATE TABLE consent_records(account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, purpose varchar(24) NOT NULL, version int NOT NULL, agreed boolean NOT NULL, agreed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(account_id,purpose));
CREATE TABLE mail_outbox(id uuid PRIMARY KEY, realm_id varchar(80) NOT NULL REFERENCES lab_runs(id) ON DELETE CASCADE, flow_id uuid NOT NULL REFERENCES signup_flows(id) ON DELETE CASCADE, generation int NOT NULL, payload_ciphertext text, key_id varchar(16) NOT NULL DEFAULT 'v1', state varchar(24) NOT NULL DEFAULT 'PENDING', attempts int NOT NULL DEFAULT 0, lease_until timestamptz, next_attempt_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(flow_id,generation));
CREATE INDEX mail_due ON mail_outbox(state,next_attempt_at);
CREATE TABLE mail_attempts(id uuid PRIMARY KEY, message_id uuid NOT NULL REFERENCES mail_outbox(id) ON DELETE CASCADE, outcome varchar(32) NOT NULL, attempted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_contexts(id uuid PRIMARY KEY, realm_id varchar(80) NOT NULL REFERENCES lab_runs(id) ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, sid_hash varchar(64) NOT NULL UNIQUE, auth_version bigint NOT NULL, authenticated_at timestamptz NOT NULL, method varchar(16) NOT NULL, revoked boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL);
CREATE TABLE oidc_transactions(id uuid PRIMARY KEY, realm_id varchar(80) NOT NULL REFERENCES lab_runs(id) ON DELETE CASCADE, flow_id uuid REFERENCES signup_flows(id) ON DELETE CASCADE, state_hash varchar(64) NOT NULL UNIQUE, nonce_hash varchar(64) NOT NULL, verifier_ciphertext text, key_id varchar(16) NOT NULL DEFAULT 'v1', context_hash varchar(64) NOT NULL, provider varchar(20) NOT NULL, issuer varchar(300) NOT NULL, intent varchar(16) NOT NULL, target_account_id uuid REFERENCES accounts(id), auth_record_id uuid REFERENCES auth_contexts(id), auth_version bigint, status varchar(20) NOT NULL DEFAULT 'PENDING', proof jsonb, expires_at timestamptz NOT NULL, proof_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identity_link_requests(transaction_id uuid PRIMARY KEY REFERENCES oidc_transactions(id) ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, status varchar(16) NOT NULL DEFAULT 'PENDING', linked_at timestamptz);
CREATE TABLE account_audit_events(id uuid PRIMARY KEY, realm_id varchar(80) NOT NULL REFERENCES lab_runs(id) ON DELETE CASCADE, request_id varchar(80) NOT NULL, event varchar(60) NOT NULL, outcome varchar(40) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE signup_flows ADD COLUMN provider_transaction_id uuid REFERENCES oidc_transactions(id);
ALTER TABLE mail_outbox ADD COLUMN lease_token uuid;
